ALTER TABLE merchant_delivery_partners ADD COLUMN "providerSyncStatus" TEXT NOT NULL DEFAULT 'NOT_REQUIRED', ADD COLUMN "providerSyncVersion" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "providerSyncError" TEXT, ADD COLUMN "providerSyncedAt" TIMESTAMP(3);
ALTER TABLE merchant_delivery_partners ADD CONSTRAINT partner_sync_status_valid CHECK ("providerSyncStatus" IN ('NOT_REQUIRED','PENDING','READY','FAILED','DISABLED'));
UPDATE merchant_delivery_partners m SET "providerSyncStatus"=CASE WHEN m."isActive" AND m."revokedAt" IS NULL THEN 'PENDING' ELSE 'DISABLED' END, "providerSyncVersion"=1 FROM delivery_partner_provider_configs c WHERE c."partnerId"=m."partnerId" AND c."integrationMode"='APP_V1' AND c."outboundWebhookUrl" ~ '/api/method/qiad_logistics\.wassla_webhooks\.receive$';
ALTER TABLE cod_collections ADD COLUMN "merchantConfirmedAt" TIMESTAMP(3), ADD COLUMN "merchantConfirmedBy" TEXT;
CREATE TABLE cod_receipts (id TEXT PRIMARY KEY, "shipmentId" TEXT NOT NULL REFERENCES platform_shipments(id) ON DELETE RESTRICT ON UPDATE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('COLLECTED','REMITTED','CONFIRMED')), amount DECIMAL(10,2) NOT NULL CHECK(amount>=0), currency TEXT NOT NULL, "actorId" TEXT NOT NULL, reference TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX cod_receipts_shipment_kind_key ON cod_receipts("shipmentId",kind);
